@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&family=DM+Sans:wght@300;400;500;600&display=swap');

:root {
  /* ── Doucy Consilium Palette ── */
  --green-deep:    #1B4332;
  --green-mid:     #2D6A4F;
  --navy:          #1A1A2E;
  --gold:          #E9A800;
  --gold-light:    #F5C842;
  --gold-dim:      rgba(233,168,0,0.12);
  --cream:         #F5F4F0;
  --white:         #FFFFFF;
  --border:        #E2DDD5;
  --text-dark:     #1A1A2E;
  --text-body:     #4A4A5A;
  --text-muted:    #8A8A9A;

  /* ── Mapping native n8n variables ── */
  --color-background:       var(--cream);
  --color-card-bg:          var(--white);
  --color-card-border:      var(--border);
  --color-card-shadow:      rgba(26,26,46,0.10);
  --color-header:           var(--navy);
  --color-label:            var(--text-body);
  --color-input-border:     var(--border);
  --color-input-text:       var(--text-dark);
  --color-focus-border:     var(--gold);
  --color-submit-btn-bg:    var(--green-deep);
  --color-submit-btn-text:  var(--white);
  --color-required:         var(--gold);
  --color-error:            #B03A2E;
  --color-link:             var(--green-mid);
  --color-html-text:        var(--text-body);
  --color-html-link:        var(--green-deep);
  --color-header-subtext:   var(--text-muted);

  --border-radius-card:     0px;
  --border-radius-input:    4px;
  --box-shadow-card:        0 0 0 1px var(--border), 0 8px 40px rgba(26,26,46,0.08);
  --submit-btn-height:      52px;
  --container-width:        520px;
  --padding-card:           48px;
}

/* ── Reset typography ── */
* { font-family: 'DM Sans', sans-serif !important; }

/* ── Background with subtle texture ── */
body {
  background-color: var(--cream) !important;
  background-image:
    radial-gradient(ellipse at 20% 50%, rgba(27,67,50,0.04) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 20%, rgba(233,168,0,0.04) 0%, transparent 60%) !important;
  min-height: 100vh !important;
  display: flex !important;
  align-items: center !important;
}

/* ── Vertical centering ── */
.container {
  padding-top: 0 !important;
  margin-top: auto !important;
  margin-bottom: auto !important;
}

/* ── Card: cabinet style ── */
.card {
  border: 1px solid var(--border) !important;
  border-top: none !important;
  border-radius: 0 !important;
  box-shadow: var(--box-shadow-card) !important;
  position: relative !important;
  overflow: visible !important;
}

/* ── Gold band at the top ── */
.card::before {
  content: '' !important;
  display: block !important;
  height: 4px !important;
  background: linear-gradient(90deg, var(--green-deep), var(--gold), var(--green-deep)) !important;
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
}

/* ── Form header ── */
.form-header {
  padding: 48px 48px 32px !important;
  text-align: center !important;
}

/* ── Logo/monogram above the title ── */
.form-header::before {
  content: 'DC' !important;
  display: block !important;
  width: 48px !important;
  height: 48px !important;
  line-height: 48px !important;
  background: var(--navy) !important;
  color: var(--gold) !important;
  font-family: 'Playfair Display', serif !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: 2px !important;
  margin: 0 auto 20px !important;
}

.form-header h1 {
  font-family: 'Playfair Display', serif !important;
  font-size: 26px !important;
  font-weight: 600 !important;
  color: var(--navy) !important;
  letter-spacing: -0.3px !important;
  line-height: 1.3 !important;
}

.form-header p {
  font-size: 14px !important;
  color: var(--text-muted) !important;
  margin-top: 10px !important;
  line-height: 1.6 !important;
  font-weight: 400 !important;
}

/* ── Gold separator below the header ── */
.form-header::after {
  content: '' !important;
  display: block !important;
  width: 40px !important;
  height: 2px !important;
  background: var(--gold) !important;
  margin: 24px auto 0 !important;
}

/* ── Zone inputs ── */
.inputs-wrapper {
  padding: 24px 48px 32px !important;
}

/* ── Labels ── */
form label {
  font-size: 11px !important;
  font-weight: 600 !important;
  letter-spacing: 1px !important;
  text-transform: uppercase !important;
  color: var(--text-muted) !important;
}

/* ── Radio buttons (main choice) ── */
.multiselect-option {
  padding: 14px 16px !important;
  border: 1px solid var(--border) !important;
  border-radius: 4px !important;
  margin-top: 8px !important;
  transition: all 0.2s ease !important;
  cursor: pointer !important;
}

.multiselect-option:hover {
  border-color: var(--gold) !important;
  background: var(--gold-dim) !important;
}

.multiselect-option label {
  font-size: 14px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
  color: var(--text-dark) !important;
  cursor: pointer !important;
}

/* ── Focus ── */
input:focus, select:focus, textarea:focus {
  outline: none !important;
  border-color: var(--gold) !important;
  box-shadow: 0 0 0 3px rgba(233,168,0,0.12) !important;
}

/* ── Submit button ── */
#submit-btn {
  font-family: 'DM Sans', sans-serif !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  letter-spacing: 1.5px !important;
  text-transform: uppercase !important;
  background: var(--green-deep) !important;
  color: var(--white) !important;
  border-radius: 0 !important;
  height: var(--submit-btn-height) !important;
  transition: background 0.25s ease, transform 0.15s ease !important;
  border: none !important;
}

#submit-btn:hover {
  background: var(--navy) !important;
  opacity: 1 !important;
  transform: translateY(-1px) !important;
}

#submit-btn:active {
  transform: translateY(0) !important;
}

/* ── Discreet n8n footer ── */
.n8n-link {
  padding: 20px 0 16px !important;
  text-align: center !important;
}
.n8n-link a {
  color: var(--border) !important;
  font-size: 10px !important;
  text-decoration: none !important;
}
.n8n-link svg path { fill: var(--border) !important; }

