const entities = $input.all().map(item => item.json);
const fields = [];

// --- CONFIGURATION TO BE MODIFIED HERE ---
const DISABLED_LABEL = "Pas de synthèse";
const HARDCODED_SOURCES = ["MyUnisoft", "Pennylane"]; 

// Dynamic construction of the list of options
const sourceOptions = HARDCODED_SOURCES.map(s => ({ option: s }));
sourceOptions.push({ option: DISABLED_LABEL });

entities.forEach(entity => {
  const siren = entity.siren;
  const name = entity.name;
  const isSubscribed = entity.is_subscribed == true;

  // HTML display
  fields.push({
    fieldLabel: "", 
    fieldType: "html", 
    fieldName: `header_${siren}`,
    html: `<div><strong>${name}</strong> <small>(SIREN: ${siren})</small></div>`
  });

  // Hidden fields
  fields.push({
    fieldLabel: `name_field_${siren}`, 
    fieldType: "hiddenField",
    fieldName: `name_field_${siren}`,
    fieldValue: name
  });

  fields.push({
    fieldLabel: `old_source_${siren}`, 
    fieldType: "hiddenField",
    fieldName: `old_source_${siren}`,
    fieldValue: entity.source_primary || ""
  });

  fields.push({
    fieldLabel: `old_sub_${siren}`, 
    fieldType: "hiddenField",
    fieldName: `old_sub_${siren}`,
    fieldValue: isSubscribed ? "true" : "false"
  });

  // Visible fields

  fields.push({
    fieldLabel: `source_${siren}`,
    fieldType: "dropdown",
    fieldName: `source_${siren}`,
    fieldOptions: { values: sourceOptions },
    defaultValue: (isSubscribed && entity.source_primary) ? entity.source_primary : DISABLED_LABEL
  });

  fields.push({
    fieldLabel: `budget_rev_${siren}`,
    fieldType: "number",
    fieldName: `budget_rev_${siren}`,
    defaultValue: entity.budget_rev || 0
  });

  fields.push({
    fieldLabel: `budget_margin_${siren}`,
    fieldType: "number",
    fieldName: `budget_margin_${siren}`,
    defaultValue: entity.budget_margin || 0
  });

  fields.push({
    fieldLabel: `budget_payroll_${siren}`,
    fieldType: "number",
    fieldName: `budget_payroll_${siren}`,
    defaultValue: entity.budget_payroll || 0
  });
});

return {
  formConfig: JSON.stringify(fields),
  count: entities.length,
  disabledLabel: DISABLED_LABEL,
  hardcodedSources: HARDCODED_SOURCES
};

