const partFormOutput = $input.first().json;
const config = $('Build Form Options').first().json;
const disabledLabel = config.disabledLabel;

// Checks if at least one key from the form is present
const hasFormData = Object.keys(partFormOutput).some(key => key.startsWith('name_field_'));

// CASE A: The user responded
if (hasFormData) {
  const data = partFormOutput;
  const companies = {};

  for (const key in data) {
    if (key.startsWith('name_field_')) {
      const siren = key.replace('name_field_', '');
      const name = data[`name_field_${siren}`];
      if (!name) continue;

      const newSource = data[`source_${siren}`];
      const isSub = newSource !== disabledLabel;
      const oldSource = data[`old_source_${siren}`];
      const oldSub = data[`old_sub_${siren}`] === 'true';

      companies[siren] = {
        name,
        siren,
        source_primary: isSub ? newSource : oldSource,
        is_subscribed: isSub,
        budget_rev: data[`budget_rev_${siren}`] ?? 0,
        budget_margin: data[`budget_margin_${siren}`] ?? 0,
        budget_payroll: data[`budget_payroll_${siren}`] ?? 0,
        old_source_primary: oldSource,
        old_subscribed_state: oldSub,
        is_modified: (isSub !== oldSub) || (isSub === true && newSource !== oldSource)
      };
    }
  }
  return Object.values(companies).map(company => ({ json: company }));
}

// CASE B: Timeout (Auto-confirmation)
return $('Batch Processing Loop').all().map(item => {
  const entity = item.json;
  return {
    json: {
      name: entity.name,
      siren: entity.siren,
      source_primary: entity.source_primary,
      is_subscribed: entity.is_subscribed == true,
      budget_rev: entity.budget_rev || 0,
      budget_margin: entity.budget_margin || 0,
      budget_payroll: entity.budget_payroll || 0,
      old_source_primary: entity.source_primary,
      old_subscribed_state: entity.is_subscribed == true,
      is_modified: false
    }
  };
});
